{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE sleepycat_db.maplemonk.sleepycat_db_attributed_FlipkartAds_Fact_items AS With CTE as ( SELECT _AIRBYTE_UNIQUE_KEY, TO_TIMESTAMP_NTZ(START_TIME) AS START_TIME, TO_TIMESTAMP_NTZ(END_TIME) AS END_TIME, ACCOUNT_ID, \"Campaign ID\" AS CAMPAIGN_ID, \"Ad Group ID\" AS AD_GROUP_ID, \"AdGroup Name\" AS ADGROUP_NAME, \"Advertised FSN ID\" AS FSN_ID, \"Advertised Product Name\" AS FSN_NAME, TRY_CAST(CTR AS DOUBLE) AS CTR, TRY_CAST(CVR AS DOUBLE) AS CVR, TRY_CAST(VIEWS AS INTEGER) AS VIEWS, TRY_CAST(CLICKS AS INTEGER) AS CLICKS, TRY_CAST(\"Ad Spend\" AS DOUBLE) AS AD_SPEND, TRY_CAST(\"ROI (Direct)\" AS DOUBLE) AS ROI_DIRECT, TRY_CAST(\"Direct Revenue\" AS DOUBLE) AS DIRECT_REVENUE, TRY_CAST(\"ROI (Indirect)\" AS DOUBLE) AS ROI_INDIRECT, TRY_CAST(\"Indirect Revenue\" AS DOUBLE) AS INDIRECT_REVENUE, TRY_CAST(\"Units Sold (Direct)\" AS INTEGER) AS UNITS_SOLD_DIRECT, TRY_CAST(\"Units Sold (Indirect)\" AS INTEGER) AS UNITS_SOLD_INDIRECT, _AIRBYTE_AB_ID, TO_TIMESTAMP_NTZ(_AIRBYTE_EMITTED_AT) AS _AIRBYTE_EMITTED_AT, TO_TIMESTAMP_NTZ(_AIRBYTE_NORMALIZED_AT) AS _AIRBYTE_NORMALIZED_AT, _AIRBYTE_SLEEPYCAT_DB_ATTRIBUTED_FSN_PLA_HASHID AS ATTRIBUTED_HASH FROM sleepycat_db.maplemonk.sleepycat_db_attributed_fsn_pla UNION ALL SELECT _AIRBYTE_UNIQUE_KEY, TO_DATE(DATE) AS START_TIME, TO_TIMESTAMP_NTZ(END_TIME) AS END_TIME, ACCOUNT_ID, CAMPAIGN_ID, NULL AS AD_GROUP_ID, NULL AS ADGROUP_NAME, FSN_ID, FSN_NAME, NULL AS CTR, NULL AS CVR, NULL AS VIEWS, NULL AS CLICKS, NULL AS AD_SPEND, NULL AS ROI_DIRECT, TRY_CAST(\"DIRECT REVENUE\" AS DOUBLE) AS DIRECT_REVENUE, NULL AS ROI_INDIRECT, TRY_CAST(\"INDIRECT REVENUE\" AS DOUBLE) AS INDIRECT_REVENUE, TRY_CAST(\"DIRECT UNITS\" AS INTEGER) AS UNITS_SOLD_DIRECT, TRY_CAST(\"INDIRECT UNITS\" AS INTEGER) AS UNITS_SOLD_INDIRECT, _AIRBYTE_AB_ID, TO_TIMESTAMP_NTZ(_AIRBYTE_EMITTED_AT) AS _AIRBYTE_EMITTED_AT, TO_TIMESTAMP_NTZ(_AIRBYTE_NORMALIZED_AT) AS _AIRBYTE_NORMALIZED_AT, _AIRBYTE_SLEEPYCAT_DB_ATTRIBUTED_FSN_PCA_HASHID AS ATTRIBUTED_HASH FROM sleepycat_db.maplemonk.sleepycat_db_attributed_fsn_pca ) Select fd.* ,fsm.name as ProductName ,fsm.category as Category ,fsm.sub_category as SubCategory ,skucode from CTE fd left join ( select marketplace_sku,name,category,sub_category,skucode from sleepycat_db.maplemonk.final_sku_master qualify row_number() over(partition by lower(marketplace_sku) order by 1) = 1 )fsm on lower(trim(fd.FSN_ID)) = lower(trim(fsm.marketplace_sku)) ; CREATE OR REPLACE TABLE sleepycat_db.maplemonk.sleepycat_db_spends_consolidated AS With FlipkartSpends as ( select start_time::Date as Date ,skucode ,\'FLIPKART\' as channel ,category ,subcategory ,productname ,sum(ifnull(ad_spend,0)) Spend from sleepycat_db.maplemonk.sleepycat_db_attributed_FlipkartAds_Fact_items group by 1,2,3,4,5,6 ), AmazonSpends as ( with amazon_spends as ( Select fd.* ,fsm.name as ProductName ,fsm.category as Category ,fsm.sub_category as SubCategory ,skucode from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_AMAZONADS_MARKETING fd left join ( select marketplace_sku,name,category,sub_category,skucode from sleepycat_db.maplemonk.final_sku_master qualify row_number() over(partition by lower(marketplace_sku) order by 1) = 1 )fsm on lower(trim(fd.asin)) = lower(trim(fsm.marketplace_sku)) ) select date::Date as Date ,skucode ,\'AMAZON\' as Channel ,category ,subcategory ,productname ,sum(ifnull(spend,0)) Spend from amazon_spends group by 1,2,3,4,5,6 ), WesiteSpends as ( select date, null as skucode, case when lower(campaign_name) like \'%store%\' then \'EBO\' else \'WEBSITE\' end as Channel, upper(Category) Category, null as subcategory, null as productname, sum(ifnull(spend,0)) Spend from sleepycat_db.maplemonk.sleepycat_db_Marketing_Consolidated s left join ( select lower(trim(\"Campaign name\")) cn,\"Product category\" Category from sleepycat_db.maplemonk.fb_gads_campaign_category_mapping_summary qualify row_number() over(partition by lower(trim(\"Campaign name\")) order by 1) = 1 )ms on lower(trim(s.campaign_name)) = lower(trim(ms.cn)) where lower(channel) like any (\'%facebook%\',\'%google%\') group by 1,2,3,4, 5,6 having sum(ifnull(spend,0)) > 0 ) Select date,skucode,channel,Category,subcategory,productname,spend from FlipkartSpends UNION ALL Select date,skucode,channel,Category,subcategory,productname,spend from AmazonSpends UNION ALL Select date,skucode,channel,Category,subcategory,productname,spend from WesiteSpends ; ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_PandL_Intermediate as select SALEORDERITEMCODE ,a.source as Marketing_Source ,(a.channel) as Marketing_Channel ,a.marketplace ,a.FINAL_MARKETPLACE ,(a.order_Date::date) as pre_Date ,a.order_id ,a.reference_code ,a.shop_name ,a.return_flag ,location_key ,a.new_customer_flag ,a.customer_id_final ,payment_mode ,payment_gateway ,a.awb ,a.order_Status ,a.shipping_status ,a.final_shipping_status ,case when lower(order_Status) like \'%cancel%\' then upper(order_status) else upper(coalesce(final_shipping_status,order_status)) end final_status ,a.sku as pre_sku ,(a.sku_code) sku_code ,a.common_sku_code ,trim(upper(a.product_name_final)) Pre_PRODUCT_NAME_FINAL ,upper(trim(a.product_sub_category)) Pre_product_sub_category ,trim(upper(a.product_category)) Pre_PRODUCT_CATEGORY ,a.quantity ,PRE_QUANTITY ,d.gst ,case when lower(ifnull(payment_gateway_name,\'\')) like \'%razorpay%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then (ifnull(selling_price,0) * 0.03) when lower(ifnull(payment_gateway_name,\'\')) like \'%snapmint%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then (ifnull(selling_price,0) * 0.04) else a.return_amount end as return_amount ,a.total_mrp ,ifnull(a.selling_price,0) + ifnull(div0(ifnull(fpl.bankshare,0),count(*) over(partition by lower(a.reference_code),lower(a.saleorderitemcode))),0) + ifnull(ifnull(GTA,0) * ifnull(pre_quantity,0),0) as selling_price ,a.shipping_price shipping_price ,d.cogs as test_cogs ,(ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) as forwardCogs ,(ifnull(d.cogs,0)*ifnull(ex_RETURNED_QUANTITY,0)) + ifnull(case when lower(ifnull(payment_gateway_name,\'\')) like \'%razorpay%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then ((ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) * 0.03) when lower(ifnull(payment_gateway_name,\'\')) like \'%snapmint%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then ((ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) * 0.04) end,0) returnCogs ,(case when lower(a.type) like \'%sale%\' then (ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) else -1*(ifnull(d.cogs,0)*ifnull(ex_RETURNED_QUANTITY,0)) end) -ifnull(case when lower(ifnull(payment_gateway_name,\'\')) like \'%razorpay%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then ((ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) * 0.03) when lower(ifnull(payment_gateway_name,\'\')) like \'%snapmint%\' and lower(FINAL_MARKETPLACE) like \'%website%\' then ((ifnull(d.cogs,0)*ifnull(PRE_QUANTITY,0)) * 0.04) end,0) as COGS ,a.tax tax ,a.RETURN_TAX ,a.type ,case when a.new_customer_flag = \'Repeat\' then LAG(a.order_date) IGNORE NULLS OVER (partition by a.customer_id_final ORDER BY a.order_date) end previous_date ,datediff(day,previous_date,a.order_Date) days_from_last_order ,otherShipmentCost ,logisticCost ,paymentgatewaycharges ,marketplaceCommission ,div0(ifnull(EBO_Rent,0),count(*) over(partition by lower(location_key),last_day(to_date(a.order_date)),lower(a.type))) as EBO_Rent ,div0(ifnull(EBO_salary,0),count(*) over(partition by lower(location_key),last_day(to_date(a.order_date)),lower(a.type))) as EBO_salary ,div0(ifnull(EBO_overhead,0),count(*) over(partition by lower(location_key),last_day(to_date(a.order_date)),lower(a.type))) as EBO_overhead ,FINAL_Mapped_Marketplace as pre_FINAL_Mapped_Marketplace ,a.EBO_Store ,div0(ifnull(fpl.bankshare,0),count(*) over(partition by lower(a.reference_code),lower(a.saleorderitemcode))) as bankshare ,ifnull(GTA,0) * ifnull(pre_quantity,0) as GTA from ( select *, Marketplace_Mapped as FINAL_Mapped_Marketplace, upper(case when lower(Marketplace_Mapped) like \'%amazon%\' then \'AMAZON\' when lower(Marketplace_Mapped) like \'%flipkart%\' then \'FLIPKART\' when lower(Marketplace_Mapped) like any (\'%website%\') then \'WEBSITE\' when lower(Marketplace_Mapped) like \'%myntra%\' then \'MYNTRA\' when lower(Marketplace_Mapped) like \'%pepperfry%\' then \'PEPPERFRY\' when lower(Marketplace_Mapped) like \'%ebo%\' then \'EBO\' else \'OTHERS\' END) as FINAL_MARKETPLACE, upper(case when lower(Marketplace_Mapped) like \'%amazon%\' then \'AMAZON\' when lower(Marketplace_Mapped) like \'%flipkart%\' then \'FLIPKART\' when lower(Marketplace_Mapped) like any (\'%website%\') then \'WEBSITE\' when lower(Marketplace_Mapped) like any (\'%zepto%\',\'%instamart%\',\'%blinkit%\') then \'QC\' when lower(Marketplace_Mapped) like any (\'%ebo%\') then \'EBO\' else marketplace END) as FINAL_MARKETPLACE_shipment_costs ,store_name as EBO_Store from ( SELECT *, upper(case when lower(shop_name) like \'%amazon%\' then \'AMAZON\' when lower(shop_name) like \'%flipkart%\' then \'FLIPKART\' when lower(shop_name) like \'%myntra%\' then \'MYNTRA\' when lower(shop_name) like \'%queuebuster%\' then \'EBO\' when lower(shop_name) like any (\'%shopify%\',\'%woocommerce%\') and lower(ifnull(payment_gateway_name,\'\')) like any (\'%snapmint%\',\'%razorpay%\',\'%cred%\',\'%bharatxpay%\') and lower(shop_name) like any (\'%shopify%\',\'%woocommerce%\') then \'WEBSITE\' when lower(shop_name) like any (\'%offline%\',\'%b2b%\') and lower(replace(reference_code,\'_\',\'&\')) like \'%&p%\' then \'PEPPERFRY\' when lower(shop_name) like any (\'%offline%\',\'%b2b%\') and lower(replace(reference_code,\'_\',\'&\')) like \'%&zp%\' then \'ZEPTO\' when lower(shop_name) like any (\'%offline%\',\'%b2b%\') and lower(replace(reference_code,\'_\',\'&\')) like \'%&mart%\' then \'INSTAMART\' else \'OTHERS\' END) Marketplace_Mapped FROM SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_db_sales_consolidated where not(lower(type) like \'%return%\' and lower(marketplace) like any (\'%shopify%\',\'%woocommerce%\',\'%website%\'))) sc left join ( Select \"Store Seller Code on EasyEcom\" key , upper(\"Store Name\") store_name, \'EBO\' as ebo_Marketplace from sleepycat_db.maplemonk.sleepycat_db_ebo_metrics qualify row_number() over(partition by lower(trim(key)) order by 1) = 1 )eb on lower(trim(location_key)) = lower(trim(key)) where ((lower(concat(reference_code,sku)) in ( ( select distinct lower(concat(reference_code,sku)) rf from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS where not(lower(ORDER_STATUS) like \'%cancel%\') and not(UPPER(replace(reference_code,\'_\',\'$\')) like any(\'%$E%\',\'%$R%\')) union (select distinct lower(concat(reference_code,sku)) from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS where (UPPER(replace(reference_code,\'_\',\'$\')) like any(\'%$E%\',\'%$R%\')) and lower(concat(SPLIT_PART(reference_code,\'_\',1),sku)) in ( select distinct lower(concat(reference_code,sku)) as sd from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS where not(UPPER(replace(reference_code,\'_\',\'$\')) like any(\'%$E%\',\'%$R%\')) and lower(ifnull(order_status,\'\')) like \'%cancel%\' ) ) union (select distinct lower(concat(ordeR_name, sku)) from sleepycat_db.maplemonk.Flipkart_sales_fact_items where event_type = \'Sale\') ) ) ) and not(lower(order_status) like \'%cancel%\')) or lower(type) like \'%return%\' ) a left join ( select \"Order ID\" flipkart_Order_id ,\"Order Item ID\" as Flipkart_item_id ,sum(abs(ifnull(\"Bank Offer Share\"::float,0))) bankShare from sleepycat_db.maplemonk.sleepycat_db_flipkart_sales_pl where lower(\"Event Type\") like \'%sale%\' group by 1,2 )fpl on lower(fpl.flipkart_Order_id) = lower(a.reference_code) and lower(fpl.Flipkart_item_id) = lower(a.saleorderitemcode) left join ( select upper(trim(sku)) as SKU, \'FLIPKART\' as MARKETPLACE, replace(gta,\',\',\'\')::float as GTA from sleepycat_db.maplemonk.sleepycat_db_flipkart_gta_skuwise qualify row_number() over(partition by upper(trim(sku)) order by 1) = 1 )gta on lower(trim(a.FINAL_MARKETPLACE)) = lower(trim(gta.MARKETPLACE)) and lower(trim(gta.SKU)) = lower(trim(a.sku)) and lower(a.TYPE) = \'sales\' left join ( select * from (select sku_code , try_to_date(start_date,\'DD-MON-YY\') start_Date , try_to_date(end_date,\'DD-MON-YY\') End_date , try_to_double(replace(mrp,\',\',\'\')) mrp , try_to_double(replace(cogs,\',\',\'\')) cogs , div0(try_to_double(replace(gst,\'%\',\'\')),100) gst ,\'sales\' as TYPE , row_number() over (partition by sku_code, start_date, end_date order by mrp desc) rw from SLEEPYCAT_DB.MAPLEMONK.SKU_MRP_COGS ) where rw=1 ) d on lower(replace(d.sku_code,\' \',\'\')) = lower(replace(a.sku,\' \',\'\')) and to_date(a.order_date)::date >= d.start_date and to_date(a.order_date)::date <= d.end_date left join ( SELECT TO_DATE(start_date, \'DD/MM/YYYY\') AS START_DATE , TO_DATE(end_date, \'DD/MM/YYYY\') AS END_DATE, upper(marketplace) as MARKETPLACE, \'sales\' AS TYPE, REPLACE(\"Cost %\", \'%\', \'\')::float/100 AS otherShipmentCost FROM sleepycat_db.maplemonk.sleepycat_db_other_shipment_cost qualify row_number() over(partition by START_DATE,END_DATE,upper(marketplace) order by 1 ) = 1 ) osc on lower(a.FINAL_MARKETPLACE_shipment_costs) = lower(osc.MARKETPLACE) and to_date(a.order_date)::date >= osc.start_date and to_date(a.order_date)::date <= osc.end_date and lower(a.TYPE) = lower(osc.TYPE) left join ( SELECT TO_DATE(end_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(start_date, \'YYYY-MM-DD\') AS START_DATE, upper(marketplace) as MARKETPLACE, \'sales\' AS TYPE, REPLACE(COMMISSION_VALUE, \'%\', \'\')::float/100 AS logisticCost FROM sleepycat_db.maplemonk.sleepycat_db_logistic_costs where marketplace is not null qualify row_number() over(partition by START_DATE,END_DATE,upper(marketplace) order by 1 ) = 1 ) a_c on lower(a.FINAL_MARKETPLACE) = lower(a_c.MARKETPLACE) and a.order_Date::date >= a_c.START_DATE and a.order_Date::date <= a_c.END_DATE and lower(a.TYPE) = lower(a_c.TYPE) left join ( SELECT TO_DATE(end_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(start_date, \'YYYY-MM-DD\') AS START_DATE, upper(marketplace) as MARKETPLACE, \'sales\' AS TYPE, REPLACE(COMMISSION_VALUE, \'%\', \'\')::float/100 AS paymentgatewaycharges FROM sleepycat_db.maplemonk.sleepycat_db_payment_gateway_charges qualify row_number() over(partition by start_date,end_date,upper(marketplace) order by 1 ) = 1 ) pgc on trim(lower(a.FINAL_MARKETPLACE)) = trim(lower(pgc.MARKETPLACE)) and to_date(a.order_date)::date >= pgc.start_date and to_date(a.order_date)::date <= pgc.end_date and lower(a.TYPE) = lower(pgc.TYPE) left join ( select upper(marketplace) Marketplace, TO_DATE(end_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(start_date, \'YYYY-MM-DD\') AS START_DATE, \'sales\' AS TYPE, upper(category) as Category, REPLACE(\"Original Commission_Value\", \'%\', \'\')::float/100 AS marketplaceCommission ,ifnull(REPLACE(\"price Start\", \',\', \'\')::float,0) as PriceStart ,ifnull(REPLACE(\"Price End\", \',\', \'\')::float,100000000000) as PriceEnd FROM sleepycat_db.maplemonk.sleepycat_db_marketplace_commissions where not(lower(marketplace) like any (\'%razor%\',\'%snap%\')) qualify row_number() over(partition by \"price Start\",\"Price End\",start_date,end_date,upper(marketplace),upper(category) order by 1 ) = 1 )mc on lower(a.FINAL_MARKETPLACE) = lower(mc.MARKETPLACE) and to_date(a.order_date)::date >= mc.start_date and to_date(a.order_date)::date <= mc.end_date and trim(lower(a.product_category)) = trim(lower(mc.category)) and lower(a.TYPE) = lower(mc.TYPE) and (div0(ifnull(a.total_mrp,0),ifnull(PRE_QUANTITY,0)) between PriceStart and PriceEnd) left join ( select upper(\"Store Seller Code on EasyEcom\") StoreCode, TO_DATE(to_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(from_date, \'YYYY-MM-DD\') AS START_DATE, \'sales\' AS TYPE, case when last_day(TO_DATE(to_date, \'YYYY-MM-DD\')) = last_day(current_date) then div0(REPLACE(rent, \',\', \'\')::float,day(last_day(current_date))) * (day((current_date))-1) else REPLACE(rent, \',\', \'\')::float end AS EBO_Rent, case when last_day(TO_DATE(to_date, \'YYYY-MM-DD\')) = last_day(current_date) then div0(REPLACE(overhead, \',\', \'\')::float,day(last_day(current_date))) * (day((current_date))-1) else REPLACE(overhead, \',\', \'\')::float end AS EBO_overhead, case when last_day(TO_DATE(to_date, \'YYYY-MM-DD\')) = last_day(current_date) then div0(REPLACE(salary, \',\', \'\')::float,day(last_day(current_date))) * (day((current_date))-1) else REPLACE(salary, \',\', \'\')::float end AS EBO_salary, FROM sleepycat_db.maplemonk.sleepycat_db_ebo_metrics qualify row_number() over(partition by start_date,end_date,upper(StoreCode) order by 1 ) = 1 )ebo on lower(a.location_key) = lower(ebo.StoreCode) and to_date(a.order_date)::date >= ebo.start_date and to_date(a.order_date)::date <= ebo.end_date and lower(a.TYPE) = lower(ebo.TYPE) ; create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_PandL as select pli.*, upper(trim(coalesce(pli.pre_sku,spc.SKUCode))) as sku, upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))) as FINAL_Mapped_Marketplace, coalesce(pre_date,spc.date,spc1.date,spc2.date)::date as Date, upper(trim(coalesce(pli.Pre_PRODUCT_CATEGORY,spc.category,spc1.category))) as PRODUCT_CATEGORY, upper(trim(coalesce(pli.Pre_PRODUCT_NAME_FINAL,spc.productname))) as PRODUCT_NAME_FINAL, upper(trim(coalesce(pli.Pre_product_sub_category,spc.subcategory))) as product_sub_category, ifnull(div0(ifnull(spc.spend,0), count(*) over(partition by upper(trim(coalesce(pli.pre_sku,spc.SKUCode))), upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))), coalesce(pre_date,spc.date,spc1.date,spc2.date) )),0) + ifnull(div0(ifnull(spc1.spend,0), count(*) over(partition by upper(trim(coalesce(pli.Pre_PRODUCT_CATEGORY,spc.category,spc1.category))), upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))), coalesce(pre_date,spc.date,spc1.date,spc2.date) )),0 ) + ifnull(div0(ifnull(spc2.spend,0), count(*) over(partition by upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel,spc2.channel))), coalesce(pre_date,spc.date,spc1.date,spc2.date)::date )),0) as Spend from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_PandL_Intermediate pli full outer join ( select date, upper(channel) as channel, upper(skucode) as SKUCode, productname, category, subcategory, (ifnull(spend,0)) as Spend from sleepycat_db.maplemonk.sleepycat_db_spends_consolidated where skucode is not null qualify row_number() over(partition by date,upper(skucode),upper(channel) order by 1) = 1 )spc on trim(lower(pli.pre_sku)) = trim(lower(spc.SKUCode)) and trim(lower(pli.pre_FINAL_Mapped_Marketplace)) = trim(lower(spc.channel)) and pli.pre_date = spc.date full outer join ( select date, upper(channel) as channel, upper(category) as Category, sum(ifnull(spend,0)) as Spend from sleepycat_db.maplemonk.sleepycat_db_spends_consolidated where skucode is null and category is not null group by 1,2,3 )spc1 on coalesce(trim(lower(pli.Pre_PRODUCT_CATEGORY)),trim(lower(spc.category))) = trim(lower(spc1.Category)) and coalesce(trim(lower(pli.pre_FINAL_Mapped_Marketplace)),trim(lower(spc.channel))) = trim(lower(spc1.channel)) and coalesce(pre_date,spc.date) = spc1.date full outer join ( select date, upper(channel) as channel, sum(ifnull(spend,0)) as Spend from sleepycat_db.maplemonk.sleepycat_db_spends_consolidated where skucode is null and category is null group by 1,2 )spc2 on upper(trim(coalesce(pli.pre_FINAL_Mapped_Marketplace,spc.channel,spc1.channel))) = upper(trim((spc2.channel))) and coalesce(pre_date,spc.date,spc1.date)::date = spc2.date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SLEEPYCAT_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            